// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 1000000000000000000);
    }

    function testFuzz_property(address actor, uint256 difficulty) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0);
        difficulty = bound(difficulty, 2, type(uint64).max);

        c.OpenToThePublic();
        c.AdjustDifficulty(difficulty);

        uint256 bet = c.currentBetLimit();
        vm.deal(actor, bet);

        vm.prank(actor, actor);
        c.wager{value: bet}();

        uint256 balAfterWager = c.ethBalance();
        bool wageredBeforePlay = c.hasPlayerWagered(actor);

        vm.prank(actor, actor);
        bool playSucceeded;
        try c.play() {
            playSucceeded = true;
        } catch {
            playSucceeded = false;
        }

        bool wageredAfterPlay = c.hasPlayerWagered(actor);
        uint256 balAfterPlay = c.ethBalance();

        assertTrue(
            !playSucceeded && wageredBeforePlay && wageredAfterPlay && balAfterPlay == balAfterWager,
            "immediate play in same block must revert and leave wager/balance intact"
        );
    }
}
